"use client";

import { Button } from "@epicbagel/saas-kit/primitives/button";
import { Icon } from "@epicbagel/saas-kit/primitives/icon";
import { Stack } from "@epicbagel/saas-kit/primitives/stack";
import { ThumbsDown, ThumbsUp } from "lucide-react";
import type { HTMLAttributes, MouseEvent, ReactNode } from "react";

/** The two calls a reviewer can make on a candidate. */
export type CandidateDecisionChoice = "yes" | "no";

/** Host-owned wording for the two buttons. */
export interface CandidateDecisionButtonsLabels {
  yes: ReactNode;
  no: ReactNode;
}

const DEFAULT_LABELS: CandidateDecisionButtonsLabels = {
  yes: "Yes",
  no: "No",
};

export interface CandidateDecisionButtonsProps
  extends Omit<HTMLAttributes<HTMLElement>, "children"> {
  /**
   * Called with the button a person pressed. Nothing is recorded yet: the
   * host usually opens its own sheet or dialog to ask why, then saves.
   */
  onChoose: (decision: CandidateDecisionChoice) => void;
  size?: "sm" | "default";
  /** Share the available width between the two buttons, as in an action bar. */
  stretch?: boolean;
  labels?: Partial<CandidateDecisionButtonsLabels>;
  /**
   * Rendered inside the group after the buttons, usually the host's reason
   * sheet. Events that bubble out of its portal then stop here with the
   * buttons' own, instead of reaching a clickable card.
   */
  children?: ReactNode;
}

/**
 * Yes and No as equal, neutral outline buttons with thumbs icons. Neither is
 * styled as the default answer.
 *
 * Unlike `CandidateDecisionBar`, which shows a recorded value as a pressed
 * option, these buttons hold no value: a press starts the host's decision
 * flow. Every click inside the group stops propagating, so the buttons work
 * inside a clickable candidate card. The root is marked
 * `data-slot="candidate-decision-buttons"`.
 */
export function CandidateDecisionButtons({
  onChoose,
  size = "sm",
  stretch = false,
  labels,
  children,
  onClick,
  ...props
}: CandidateDecisionButtonsProps) {
  const text = { ...DEFAULT_LABELS, ...labels };

  return (
    <Stack
      data-slot="candidate-decision-buttons"
      direction="horizontal"
      gap="sm"
      grow={stretch}
      {...props}
      onClick={(event: MouseEvent<HTMLElement>) => {
        event.stopPropagation();
        onClick?.(event);
      }}
    >
      <Button grow={stretch} size={size} variant="outline" onClick={() => onChoose("yes")}>
        <Icon icon={ThumbsUp} size="sm" /> {text.yes}
      </Button>
      <Button grow={stretch} size={size} variant="outline" onClick={() => onChoose("no")}>
        <Icon icon={ThumbsDown} size="sm" /> {text.no}
      </Button>
      {children}
    </Stack>
  );
}

"use client";

import { Badge } from "@epicbagel/saas-kit/primitives/badge";
import { Button } from "@epicbagel/saas-kit/primitives/button";
import {
  Dialog,
  DialogContent,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@epicbagel/saas-kit/primitives/dialog";
import { Icon } from "@epicbagel/saas-kit/primitives/icon";
import { Label } from "@epicbagel/saas-kit/primitives/label";
import { Stack } from "@epicbagel/saas-kit/primitives/stack";
import { Text } from "@epicbagel/saas-kit/primitives/text";
import { Textarea } from "@epicbagel/saas-kit/primitives/textarea";
import { Loader2 } from "lucide-react";
import { useEffect, useId, useState, type ReactNode } from "react";

/** Host-owned wording for the dialog's fixed parts. */
export interface CandidateDecisionReasonDialogLabels {
  /** The eyebrow over the suggestion chips. */
  suggestions: ReactNode;
  /** The reason field's label. */
  reason: ReactNode;
  cancel: ReactNode;
}

const DEFAULT_LABELS: CandidateDecisionReasonDialogLabels = {
  suggestions: "Tap a signal to use it as the reason",
  reason: "Why?",
  cancel: "Cancel",
};

/** Joins a tapped suggestion onto the reason typed so far. */
const SUGGESTION_SEPARATOR = " · ";

export interface CandidateDecisionReasonDialogProps {
  open: boolean;
  /** Names the decision and the candidate, such as "Reject: Mei Tanaka". */
  title: ReactNode;
  /** One-tap reasons, already worded. Tapping one adds it to the reason. */
  suggestions?: readonly string[];
  placeholder: string;
  confirmLabel: ReactNode;
  /** `destructive` for a rejection, `default` to move forward. */
  confirmTone?: "default" | "destructive";
  /**
   * Called with the trimmed reason. The confirm button shows a spinner and
   * the dialog's buttons stay disabled until it settles; the host closes the
   * dialog once the decision is saved.
   */
  onSubmit: (reason: string) => Promise<void>;
  /** Called from Cancel, Escape and the close button. */
  onClose: () => void;
  labels?: Partial<CandidateDecisionReasonDialogLabels>;
  /** The reason field's id. A generated one is used when omitted. */
  id?: string;
}

/**
 * Asks why before a decision on a candidate is recorded: a required reason,
 * optionally started from one-tap suggestions.
 *
 * The reason resets each time the dialog opens. The host owns the decision,
 * its wording and what is saved; the root is the kit's dialog content and
 * keeps its `data-slot="dialog-content"`.
 */
export function CandidateDecisionReasonDialog(props: CandidateDecisionReasonDialogProps) {
  // Only generate an id when the host has not supplied one, so a host id
  // costs nothing.
  return props.id ? (
    <ReasonDialog {...props} id={props.id} />
  ) : (
    <ReasonDialogWithGeneratedId {...props} />
  );
}

function ReasonDialogWithGeneratedId(props: CandidateDecisionReasonDialogProps) {
  const id = useId();
  return <ReasonDialog {...props} id={id} />;
}

function ReasonDialog({
  open,
  title,
  suggestions = [],
  placeholder,
  confirmLabel,
  confirmTone = "default",
  onSubmit,
  onClose,
  labels,
  id,
}: CandidateDecisionReasonDialogProps & { id: string }) {
  const text = { ...DEFAULT_LABELS, ...labels };
  const [reason, setReason] = useState("");
  const [submitting, setSubmitting] = useState(false);

  useEffect(() => {
    if (!open) return;
    setReason("");
    setSubmitting(false);
  }, [open]);

  const submit = async () => {
    setSubmitting(true);
    try {
      await onSubmit(reason.trim());
    } finally {
      setSubmitting(false);
    }
  };

  return (
    <Dialog open={open} onOpenChange={(next) => !next && onClose()}>
      <DialogContent size="sm">
        <DialogHeader>
          <DialogTitle size="base">{title}</DialogTitle>
        </DialogHeader>
        <Stack direction="vertical" gap="sm">
          {suggestions.length > 0 && (
            <Stack gap="none">
              <Text as="div" variant="eyebrow" marginBottom="sm">
                {text.suggestions}
              </Text>
              <Stack direction="horizontal" gap="xs" wrap>
                {suggestions.map((suggestion, index) => (
                  <Badge
                    key={index}
                    variant="outline"
                    size="micro"
                    weight="normal"
                    interactive
                    onClick={() =>
                      setReason((current) => (current ? `${current}${SUGGESTION_SEPARATOR}${suggestion}` : suggestion))
                    }
                  >
                    {suggestion}
                  </Badge>
                ))}
              </Stack>
            </Stack>
          )}
          <Stack gap="xs">
            <Label htmlFor={id} appearance="eyebrow">
              {text.reason}
            </Label>
            <Textarea
              id={id}
              value={reason}
              onChange={(event) => setReason(event.target.value)}
              rows={3}
              placeholder={placeholder}
              autoFocus
            />
          </Stack>
        </Stack>
        <DialogFooter>
          <Button variant="ghost" onClick={onClose} disabled={submitting}>
            {text.cancel}
          </Button>
          <Button
            onClick={submit}
            disabled={submitting || reason.trim().length === 0}
            variant={confirmTone}
          >
            {submitting ? <Icon icon={Loader2} size="md" spin /> : null}
            {confirmLabel}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

import { Badge } from "@epicbagel/saas-kit/primitives/badge";
import { Card } from "@epicbagel/saas-kit/primitives/card";
import { FlexItem } from "@epicbagel/saas-kit/primitives/flex-item";
import { PanelSection } from "@epicbagel/saas-kit/primitives/panel-section";
import { Stack } from "@epicbagel/saas-kit/primitives/stack";
import { StatusIconTile } from "@epicbagel/saas-kit/primitives/status-icon-tile";
import { Text } from "@epicbagel/saas-kit/primitives/text";
import { Flag } from "lucide-react";
import type { HTMLAttributes, ReactNode } from "react";

import type { CandidateGradeTone } from "./candidate-grade";

/** A recorded decision on the person for one role. */
export interface CandidateDecisionSummaryDecision {
  /** Whose decision it is, such as "Your decision". */
  heading: ReactNode;
  /** The verdict, such as "Yes". */
  verdict: ReactNode;
  /** Colours the flag tile and the verdict. */
  tone: "positive" | "negative";
  /** Where the decision left the person, such as their stage. */
  stage: ReactNode;
  /** Why, kept as written. */
  reason?: ReactNode;
}

/** An automated assessment of the person for the same role. */
export interface CandidateDecisionSummaryAssessment {
  /** The grade in the tile, such as "A". */
  letter: ReactNode;
  /** The tile's badge tone. */
  tone: CandidateGradeTone;
  /** The tile's tooltip. */
  title?: string;
  /** The row's eyebrow, such as "AI assessment". */
  heading: ReactNode;
  /** What the grade means, and anything still pending. */
  label: ReactNode;
}

export interface CandidateDecisionSummaryProps
  extends Omit<HTMLAttributes<HTMLElement>, "children"> {
  decision?: CandidateDecisionSummaryDecision;
  assessment?: CandidateDecisionSummaryAssessment;
}

/**
 * The headline of a person's detail for the role in focus: the recorded
 * decision with a flag tile, and the assessment grade in a tile, in one card
 * on a muted band. Either row may be left out; with neither it renders
 * nothing. Unlike CandidateAssessment, which lays out a full write-up, this
 * is a two-line summary.
 *
 * The root is the kit PanelSection, marked `data-slot="candidate-decision-summary"`.
 */
export function CandidateDecisionSummary({
  decision,
  assessment,
  ...props
}: CandidateDecisionSummaryProps) {
  if (!decision && !assessment) return null;
  const positive = decision?.tone === "positive";
  const reason = decision?.reason;

  return (
    <PanelSection data-slot="candidate-decision-summary" border="bottom" surface="muted" {...props}>
      <Card overflow="hidden">
        {decision && (
          <Stack direction="horizontal" gap="sm" align="start" padding="compact">
            <StatusIconTile icon={Flag} tone={positive ? "success" : "destructive"} />
            <FlexItem minWidth="zero">
              <Text variant="eyebrow" weight="semibold">{decision.heading}</Text>
              <Stack direction="horizontal" gap="xs" marginTop="xs" align="baseline" textSize="sm">
                <Text variant="inherit" as="span" weight="semibold" tone={positive ? "success" : "destructive"}>
                  {decision.verdict}
                </Text>
                <Text variant="inherit" as="span" tone="muted">· {decision.stage}</Text>
              </Stack>
              {reason != null && reason !== false && reason !== "" && (
                <Text size="sm" tone="muted" marginTop="tight" whitespace="pre-wrap">{reason}</Text>
              )}
            </FlexItem>
          </Stack>
        )}

        {assessment && (
          <Stack
            direction="horizontal"
            gap="compact"
            align="start"
            paddingX="md"
            paddingY="section"
            border={decision ? "top" : "none"}
          >
            <Badge
              variant={assessment.tone}
              size="tile"
              shape="rounded"
              weight="bold"
              shrink
              marginTop="tight"
              title={assessment.title}
            >
              {assessment.letter}
            </Badge>
            <FlexItem minWidth="zero">
              <Text variant="eyebrow" weight="semibold">{assessment.heading}</Text>
              <Text size="sm" tone="muted" marginTop="tight">{assessment.label}</Text>
            </FlexItem>
          </Stack>
        )}
      </Card>
    </PanelSection>
  );
}

