"use client";

import { FlexItem } from "@epicbagel/saas-kit/primitives/flex-item";
import { Heading } from "@epicbagel/saas-kit/primitives/heading";
import { InteractiveCard } from "@epicbagel/saas-kit/primitives/interactive-card";
import { Stack } from "@epicbagel/saas-kit/primitives/stack";
import { Text } from "@epicbagel/saas-kit/primitives/text";
import { useId, type HTMLAttributes, type MouseEvent, type ReactNode } from "react";

import { shouldActivateCandidateCard } from "./candidate-card-activation";
import { COARSE_POINTER_TOUCH_TARGETS_WITHIN } from "./touch-targets";

export interface CandidateInlineCardProps
  extends Omit<HTMLAttributes<HTMLElement>, "onClick" | "title"> {
  name: ReactNode;
  avatar?: ReactNode;
  headline?: ReactNode;
  /**
   * The caption line under the headline, such as a location. A leading glyph
   * (an `svg`, such as the kit's Icon, passed before the text) sits on the
   * text's line, centred on its capitals, with a small gap after it.
   */
  meta?: ReactNode;
  assessment?: ReactNode;
  status?: ReactNode;
  actions?: ReactNode;
  selected?: boolean;
  subdued?: boolean;
  onSelect?: () => void;
  selectLabel?: string;
  /**
   * `comfortable` (the default) gives the card room for an assessment;
   * `compact` is a single dense row (smaller padding, the name and lines
   * centred on the avatar, every line truncated) for fixed-height list rows
   * and board columns: give the card a height and its content centres in it.
   * On a coarse pointer (a touchscreen) every link and button in a compact
   * card's `actions` is at least 44px square, whatever size it asked for, so
   * a dense row keeps its touch targets on a phone.
   */
  density?: CandidateInlineCardDensity;
}

/** How much room a CandidateInlineCard takes. */
export type CandidateInlineCardDensity = "comfortable" | "compact";

/**
 * A glyph in the meta line stays on the text's line. The stylesheet reset
 * makes every `svg` a block, which would put it on a line of its own above
 * the text; inline, the line still wraps, and still truncates with an
 * ellipsis when compact, as plain text does. Centred on a capital for a
 * glyph as tall as the text; the gap matches the kit's icon-and-text rows.
 */
const META_LINE_GLYPHS =
  "[&>svg]:inline-block [&>svg]:align-[-0.125em] [&>svg]:me-1.5";

/**
 * A compact candidate trigger suitable for lists, messages, and previews.
 *
 * The root is the kit InteractiveCard as an `article`, marked
 * `data-slot="candidate-inline-card"` and `data-density`. The `actions` sit in
 * an element marked `data-slot="candidate-inline-card-actions"` that takes no
 * box of its own (`display: contents`), so they lay out as before. The meta
 * line is marked `data-slot="candidate-inline-card-meta"`.
 */
export function CandidateInlineCard({
  name,
  avatar,
  headline,
  meta,
  assessment,
  status,
  actions,
  selected = false,
  subdued = false,
  onSelect,
  selectLabel = "Open candidate profile",
  density = "comfortable",
  "aria-expanded": ariaExpanded,
  className,
  ...props
}: CandidateInlineCardProps) {
  const generatedId = useId();
  const nameId = `${generatedId}-name`;
  const actionId = `${generatedId}-action`;
  const compact = density === "compact";

  return (
    <InteractiveCard
      as="article"
      data-slot="candidate-inline-card"
      data-density={density}
      selected={selected}
      borderWidth="thin"
      padding="none"
      opacity={subdued ? "subdued" : "full"}
      className={className}
      {...props}
    >
      {onSelect ? (
        <button
          type="button"
          data-slot="candidate-inline-card-trigger"
          aria-label={selectLabel === "Open candidate profile" ? undefined : selectLabel}
          aria-labelledby={selectLabel === "Open candidate profile" ? `${actionId} ${nameId}` : undefined}
          aria-current={selected || undefined}
          aria-expanded={ariaExpanded}
          className="pointer-events-none absolute inset-0 z-10 rounded-[inherit] border-0 bg-transparent p-0 focus-visible:outline-hidden focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2"
          onClick={onSelect}
        >
          {selectLabel === "Open candidate profile" ? (
            <span id={actionId} className="sr-only">{selectLabel}</span>
          ) : null}
        </button>
      ) : null}
      <div
        data-slot="candidate-inline-card-content"
        // Compact fills a fixed-height row and centres on it, as a virtualised list needs.
        className={compact ? "h-full px-3 py-2" : "px-5 py-4"}
        onClick={
          onSelect
            ? (event: MouseEvent<HTMLDivElement>) => {
                if (shouldActivateCandidateCard(event)) onSelect();
              }
            : undefined
        }
      >
        <Stack
          direction="horizontal"
          gap={compact ? "sm" : "compact"}
          align={compact ? "center" : "start"}
          height={compact ? "full" : "auto"}
        >
          {avatar}
          <FlexItem grow minWidth="zero">
            <Stack direction="horizontal" gap="sm" align="center" wrap={!compact}>
              <Heading id={nameId} level={5} appearance={compact ? "compact" : "default"} truncate>{name}</Heading>
              {status}
            </Stack>
            {headline != null ? (
              // A compact row is a fixed height: the caption's relaxed leading would push the lines apart.
              <Text
                variant="caption"
                size={compact ? "xs" : "sm"}
                leading={compact ? "snug" : "normal"}
                truncate
                marginTop={compact ? "none" : "tight"}
              >
                {headline}
              </Text>
            ) : null}
            {meta != null ? (
              <Text
                data-slot="candidate-inline-card-meta"
                variant="caption"
                size="xs"
                leading={compact ? "snug" : "normal"}
                truncate={compact}
                marginTop={compact ? "none" : "xs"}
                className={META_LINE_GLYPHS}
              >
                {meta}
              </Text>
            ) : null}
            {assessment != null ? (
              <Stack gap="none" marginTop={compact ? "sm" : "md"}>{assessment}</Stack>
            ) : null}
          </FlexItem>
          {actions != null ? (
            // No box of its own, so the actions stay items of the row; it
            // only carries a compact row's touch targets to its controls.
            <div
              data-slot="candidate-inline-card-actions"
              className={compact ? `contents ${COARSE_POINTER_TOUCH_TARGETS_WITHIN}` : "contents"}
            >
              {actions}
            </div>
          ) : null}
        </Stack>
      </div>
    </InteractiveCard>
  );
}

import { PanelSection } from "@epicbagel/saas-kit/primitives/panel-section";
import { Stack } from "@epicbagel/saas-kit/primitives/stack";
import { Text } from "@epicbagel/saas-kit/primitives/text";
import type { HTMLAttributes, ReactNode } from "react";

/** One titled passage of evidence. */
export interface CandidateJobEvidenceEntry {
  /** The heading, such as "Why sourced for Staff Engineer". */
  title: ReactNode;
  /** The passage, kept as written: line breaks are preserved. */
  text: ReactNode;
}

/** A person's judgement of the candidate for the role. */
export interface CandidateJobEvidenceFeedback extends CandidateJobEvidenceEntry {
  /** Who gave it and when, already worded, under the passage. */
  byline?: ReactNode;
}

export interface CandidateJobEvidenceProps
  extends Omit<HTMLAttributes<HTMLElement>, "children"> {
  /** Why the person was put forward for the role. */
  sourced?: CandidateJobEvidenceEntry;
  /** A recruiter's feedback on the person for the role. */
  feedback?: CandidateJobEvidenceFeedback;
  /** The kit PanelSection's padding. */
  padding?: "none" | "compact" | "default";
  /** The kit PanelSection's divider. */
  border?: "none" | "top" | "bottom";
}

/**
 * The evidence attached to a person for one role, kept with that role: why
 * they were sourced for it, and a recruiter's feedback with its byline.
 * Render one per role so neither passage is mistaken for another role's.
 * With neither passage it renders nothing.
 *
 * The root is the kit PanelSection, marked `data-slot="candidate-job-evidence"`.
 */
export function CandidateJobEvidence({
  sourced,
  feedback,
  padding = "compact",
  border = "none",
  ...props
}: CandidateJobEvidenceProps) {
  if (!sourced && !feedback) return null;
  const byline = feedback?.byline;

  return (
    <PanelSection data-slot="candidate-job-evidence" padding={padding} border={border} {...props}>
      <Stack gap="sm">
        {sourced && (
          <Stack gap="xs">
            <Text size="sm" weight="semibold">{sourced.title}</Text>
            <Text size="sm" whitespace="pre-wrap">{sourced.text}</Text>
          </Stack>
        )}
        {feedback && (
          <Stack gap="xs">
            <Text size="sm" weight="semibold">{feedback.title}</Text>
            <Text size="sm" whitespace="pre-wrap">{feedback.text}</Text>
            {byline != null && byline !== false && byline !== "" && (
              <Text size="xs" tone="muted">{byline}</Text>
            )}
          </Stack>
        )}
      </Stack>
    </PanelSection>
  );
}

"use client";

import { Badge } from "@epicbagel/saas-kit/primitives/badge";
import { Button } from "@epicbagel/saas-kit/primitives/button";
import { Card } from "@epicbagel/saas-kit/primitives/card";
import { EmptyState } from "@epicbagel/saas-kit/primitives/empty-state";
import { Icon } from "@epicbagel/saas-kit/primitives/icon";
import { PanelSection } from "@epicbagel/saas-kit/primitives/panel-section";
import { SectionHeader } from "@epicbagel/saas-kit/primitives/section-header";
import { Skeleton } from "@epicbagel/saas-kit/primitives/skeleton";
import { Stack } from "@epicbagel/saas-kit/primitives/stack";
import { Text } from "@epicbagel/saas-kit/primitives/text";
import { Textarea } from "@epicbagel/saas-kit/primitives/textarea";
import { Loader2, MessageSquare, Mic, Sparkles, StickyNote, Trash2 } from "lucide-react";
import { useState, type HTMLAttributes, type ReactNode } from "react";

import type { CandidateEmptyCopy } from "./candidate-empty-copy";

function present(value: ReactNode): boolean {
  return value != null && value !== false && value !== "";
}

export interface CandidateNoteListProps
  extends Omit<HTMLAttributes<HTMLElement>, "title" | "children"> {
  /** How many notes there are. Zero shows the empty state instead of `children`. */
  count: number;
  /** A skeleton row in place of the list, and no count yet. */
  loading?: boolean;
  /** The section heading. */
  title?: ReactNode;
  /** The blank slate's wording. Defaults to "No notes yet". */
  empty?: CandidateEmptyCopy;
  /** Below the notes, usually a CandidateNoteComposer. */
  composer?: ReactNode;
  /** The notes, usually CandidateNoteCards, newest or pinned first. */
  children?: ReactNode;
  /** The kit PanelSection's divider. */
  border?: "none" | "top" | "bottom";
}

/**
 * The notes on one person, as a counted section: a skeleton row while they
 * load, then the host's note cards, or the kit's empty state when there are
 * none, with the composer underneath so a new note lands below the last.
 *
 * The root is the kit PanelSection, marked `data-slot="candidate-note-list"`.
 */
export function CandidateNoteList({
  count,
  loading = false,
  title = "Notes",
  empty = { title: "No notes yet" },
  composer,
  children,
  border = "bottom",
  ...props
}: CandidateNoteListProps) {
  return (
    <PanelSection data-slot="candidate-note-list" border={border} {...props}>
      <SectionHeader label={title} count={loading ? undefined : count} />
      {loading ? (
        <Stack direction="vertical" gap="sm" marginTop="md">
          <Skeleton preset="row" radius="xl" />
        </Stack>
      ) : count > 0 ? (
        <Stack direction="vertical" gap="sm" marginTop="md">
          {children}
        </Stack>
      ) : (
        <EmptyState
          variant="empty"
          size="inline"
          icon={StickyNote}
          title={empty.title}
          description={empty.description}
        />
      )}
      {composer}
    </PanelSection>
  );
}

/** How a note was left, which picks its glyph: dictated, written by an assistant, or typed. */
export type CandidateNoteKind = "voice" | "agent" | "note";

/** Marks a note that stays at the top of the list and is edited elsewhere. */
export interface CandidateNotePinned {
  /** The badge text, such as "Client note · pinned". */
  label: ReactNode;
  /** The badge tooltip, such as where to edit it. */
  title?: string;
}

/** Which role, if any, the note belongs to. */
export interface CandidateNoteScope {
  /** The badge text, such as the role's title or "General". */
  label: ReactNode;
  /** The badge tooltip. */
  title?: string;
  /** An info-toned badge, for a note tied to a role, instead of the neutral one. */
  highlighted?: boolean;
}

export interface CandidateNoteCardLabels {
  /** After the author on a dictated note. Pass `null` to leave it out. */
  voice: ReactNode;
  /** The delete button's tooltip and accessible name. */
  delete: string;
}

const NOTE_CARD_LABELS: CandidateNoteCardLabels = {
  voice: "· voice",
  delete: "Delete note",
};

const NOTE_ICON = { voice: Mic, agent: Sparkles, note: MessageSquare } as const;

export interface CandidateNoteCardProps
  extends Omit<HTMLAttributes<HTMLDivElement>, "children"> {
  /** Who left it, already resolved to a display name. */
  author: ReactNode;
  kind?: CandidateNoteKind;
  /** Pins the note: it sits on the card surface, not the muted one, with this badge. */
  pinned?: CandidateNotePinned;
  scope?: CandidateNoteScope;
  /** When it was left, already formatted. */
  date?: ReactNode;
  /** The note, kept as written: line breaks are preserved. */
  text?: ReactNode;
  /** Adds a delete button. Confirm in the host before deleting anything. */
  onDelete?: () => void;
  /** Whether the delete button is always shown or appears on hover. Use `always` on touch screens. */
  revealDelete?: "always" | "hover";
  labels?: Partial<CandidateNoteCardLabels>;
}

/**
 * One note on a person: who left it and how, an optional pinned badge, the
 * role it belongs to, when, and the text, with a delete button that appears
 * on hover or always. The host resolves authors and roles and confirms
 * deletes.
 *
 * The root is the kit Card and keeps the kit's own `data-slot="card"`, which
 * theme stylesheets select on.
 */
export function CandidateNoteCard({
  author,
  kind = "note",
  pinned,
  scope,
  date,
  text,
  onDelete,
  revealDelete = "hover",
  labels,
  ...props
}: CandidateNoteCardProps) {
  const voiceLabel = labels?.voice !== undefined ? labels.voice : NOTE_CARD_LABELS.voice;
  const deleteLabel = labels?.delete ?? NOTE_CARD_LABELS.delete;

  return (
    <Card interaction="group" surface={pinned ? "card" : "muted"} padding="row" {...props}>
      <Stack direction="horizontal" gap="none" align="center" justify="between" marginBottom="md">
        <Stack direction="horizontal" gap="sm" align="center" textSize="xs" tone="muted" wrap>
          <Text variant="inherit" as="span" display="inline-flex" weight="medium" tone="soft">
            <Icon icon={NOTE_ICON[kind]} size="xs" />
            {author}
          </Text>
          {pinned && (
            <Badge as="span" variant="info" size="micro" weight="semibold" title={pinned.title}>
              {pinned.label}
            </Badge>
          )}
          {kind === "voice" && present(voiceLabel) && (
            <Text variant="inherit" as="span" tone="subtle">{voiceLabel}</Text>
          )}
          {scope && (
            <Badge
              as="span"
              variant={scope.highlighted ? "info" : "default"}
              size="micro"
              weight="semibold"
              title={scope.title}
            >
              {scope.label}
            </Badge>
          )}
        </Stack>
        <Stack direction="horizontal" gap="xs" align="center">
          {date}
          {onDelete && (
            <Button
              type="button"
              size="icon-sm"
              reveal={revealDelete === "always" ? "always" : "parent-hover-responsive"}
              variant="ghost-destructive"
              onClick={() => onDelete()}
              title={deleteLabel}
            >
              <Icon icon={Trash2} size="sm" />
            </Button>
          )}
        </Stack>
      </Stack>
      {present(text) && <Text size="sm" whitespace="pre-wrap">{text}</Text>}
    </Card>
  );
}

export interface CandidateNoteComposerLabels {
  /** Under the microphone, and its accessible name. */
  voice: string;
  /** The link that switches to typing. */
  type: string;
  placeholder: string;
  cancel: string;
  submit: string;
}

const COMPOSER_LABELS: CandidateNoteComposerLabels = {
  voice: "Tap to speak",
  type: "or type instead",
  placeholder: "Type your note…",
  cancel: "Cancel",
  submit: "Add note",
};

export interface CandidateNoteComposerProps
  extends Omit<HTMLAttributes<HTMLElement>, "children" | "onSubmit"> {
  /** Starts dictation. The host records the note and saves it. Without it the microphone does nothing. */
  onVoice?: () => void;
  /**
   * Saves a typed note or a picked suggestion, trimmed. Resolve once saved:
   * the composer then clears and closes. Reject and the typed text stays.
   */
  onSubmit: (text: string) => Promise<void>;
  /** One-tap notes under the microphone, each saved as written. */
  suggestions?: readonly string[];
  labels?: Partial<CandidateNoteComposerLabels>;
}

/**
 * Leaves a note on a person, voice first: a large microphone, a link to type
 * instead, and one-tap suggestions. Typing opens a text area with Cancel and
 * Add note; Add note stays disabled until there is text and shows a spinner
 * while the host saves.
 *
 * The root is marked `data-slot="candidate-note-composer"`.
 */
export function CandidateNoteComposer({
  onVoice,
  onSubmit,
  suggestions = [],
  labels,
  ...props
}: CandidateNoteComposerProps) {
  const copy = { ...COMPOSER_LABELS, ...labels };
  const [typing, setTyping] = useState(false);
  const [text, setText] = useState("");
  const [saving, setSaving] = useState(false);

  const submit = async (note: string) => {
    const trimmed = note.trim();
    if (!trimmed) return;
    setSaving(true);
    try {
      await onSubmit(trimmed);
      setText("");
      setTyping(false);
    } catch {
      // The host reports the failure; keep what was typed.
    } finally {
      setSaving(false);
    }
  };

  if (typing) {
    return (
      <Stack data-slot="candidate-note-composer" direction="vertical" gap="sm" marginTop="md" {...props}>
        <Textarea
          resize="none"
          placeholder={copy.placeholder}
          value={text}
          onChange={(event) => setText(event.target.value)}
          autoFocus
        />
        <Stack direction="horizontal" gap="sm" align="center">
          <Button size="sm" variant="ghost" onClick={() => { setTyping(false); setText(""); }}>
            {copy.cancel}
          </Button>
          <Button size="sm" onClick={() => void submit(text)} disabled={!text.trim() || saving}>
            {saving ? <Icon icon={Loader2} size="sm" spin /> : copy.submit}
          </Button>
        </Stack>
      </Stack>
    );
  }

  return (
    <Stack data-slot="candidate-note-composer" direction="vertical" gap="sm" marginTop="md" {...props}>
      <Stack direction="vertical" gap="sm" align="center" paddingY="md">
        <Button type="button" variant="outline" size="voice" aria-label={copy.voice} onClick={() => onVoice?.()}>
          <Icon icon={Mic} size={28} tone="muted" />
        </Button>
        <Text variant="inherit" as="span" size="sm" weight="medium">{copy.voice}</Text>
        <Button type="button" variant="quiet" size="bare" onClick={() => setTyping(true)}>
          {copy.type}
        </Button>
      </Stack>

      {suggestions.length > 0 && (
        <Stack direction="horizontal" gap="xs" justify="center" wrap>
          {suggestions.map((suggestion) => (
            <Button
              key={suggestion}
              type="button"
              variant="outline-muted"
              size="suggestion"
              onClick={() => void submit(suggestion)}
            >
              {suggestion}
            </Button>
          ))}
        </Stack>
      )}
    </Stack>
  );
}

"use client";

import { Badge } from "@epicbagel/saas-kit/primitives/badge";
import { Button } from "@epicbagel/saas-kit/primitives/button";
import { Icon } from "@epicbagel/saas-kit/primitives/icon";
import { PanelSection } from "@epicbagel/saas-kit/primitives/panel-section";
import { SectionHeader } from "@epicbagel/saas-kit/primitives/section-header";
import { Stack } from "@epicbagel/saas-kit/primitives/stack";
import { Text } from "@epicbagel/saas-kit/primitives/text";
import { Textarea } from "@epicbagel/saas-kit/primitives/textarea";
import { Check, Copy, Loader2, MessageSquare, RefreshCw, Settings2 } from "lucide-react";
import type { HTMLAttributes, ReactNode } from "react";

function present(value: ReactNode): boolean {
  return value != null && value !== false && value !== "";
}

/** A channel a message can be drafted for. */
export interface CandidateOutreachChannel<TValue extends string = string> {
  value: TValue;
  /** The channel's name, on its button and in the default wording. */
  label: string;
}

/**
 * The house style a draft follows on the current channel, which a person
 * can edit in place. The host keeps the edit's state and saves it.
 */
export interface CandidateOutreachGuidance {
  /** The guidance in force, shown on one truncated line. */
  text: ReactNode;
  /** Marks the guidance as changed from your default. */
  custom?: boolean;
  /** Shows the editor in place of the line. */
  editing: boolean;
  /** The editor's text. */
  value: string;
  /** Shows a spinner on Save and disables it. */
  saving?: boolean;
  /** Set false to disable Save, for example when there is nowhere to save to. */
  canSave?: boolean;
  /** Opens the editor; seed `value` with the guidance in force. */
  onEdit: () => void;
  onChange: (value: string) => void;
  /** Puts your default back in the editor. */
  onReset: () => void;
  onSave: () => void;
  onCancel: () => void;
}

/** A drafted message, which a person can edit before copying it. */
export interface CandidateOutreachDraft {
  /** Shown above the message, for channels that have one. */
  subject?: ReactNode;
  message: string;
  /** The tone the draft took, shown beside Redo and Copy. */
  tone?: ReactNode;
}

export interface CandidateOutreachComposerLabels {
  title: ReactNode;
  /** The editor's heading, from the channel's label. Shown in capitals. */
  guidanceHeading: (channel: string) => ReactNode;
  reset: string;
  cancel: string;
  save: string;
  /** The badge on custom guidance. */
  custom: string;
  /** The draft button, from the channel's label. */
  draft: (channel: string) => string;
  drafting: string;
  /** Before the subject. */
  subject: string;
  /** Before the tone. */
  tone: string;
  redo: string;
  copy: string;
  copied: string;
}

const LABELS: CandidateOutreachComposerLabels = {
  title: "Outreach",
  guidanceHeading: (channel) => `${channel} tone`,
  reset: "Reset default",
  cancel: "Cancel",
  save: "Save",
  custom: "custom",
  draft: (channel) => `Draft ${channel} message`,
  drafting: "Drafting...",
  subject: "Subject: ",
  tone: "Tone: ",
  redo: "Redo",
  copy: "Copy",
  copied: "Copied",
};

export interface CandidateOutreachComposerProps<TValue extends string = string>
  extends Omit<HTMLAttributes<HTMLElement>, "title" | "children" | "onCopy"> {
  /** The channels, in order, as buttons in the header. */
  channels: readonly CandidateOutreachChannel<TValue>[];
  channel: TValue;
  onChannelChange: (value: TValue) => void;
  guidance: CandidateOutreachGuidance;
  /** The draft for the current channel. Without one, the composer offers to write it. */
  draft?: CandidateOutreachDraft | null;
  /** Shows the draft's progress and disables Draft and Redo. */
  drafting?: boolean;
  /** Why the last draft failed. */
  error?: ReactNode;
  /** Shows Copied, with a check, in place of Copy. */
  copied?: boolean;
  /** Writes a draft, or a fresh one. */
  onDraft: () => void;
  /** Copies the draft; the host decides what goes on the clipboard. */
  onCopy: () => void;
  onEditDraft: (message: string) => void;
  labels?: Partial<CandidateOutreachComposerLabels>;
  /** The kit PanelSection's divider. */
  border?: "none" | "top" | "bottom";
}

/**
 * Drafts a first message to a person: a channel picker in the header, the
 * house style for that channel on one line (which opens an editor), a button
 * that drafts the message, then the editable draft with its tone, Redo and
 * Copy. The host writes the draft, keeps the guidance and owns the clipboard.
 *
 * The root is the kit PanelSection, marked `data-slot="candidate-outreach-composer"`.
 */
export function CandidateOutreachComposer<TValue extends string = string>({
  channels,
  channel,
  onChannelChange,
  guidance,
  draft,
  drafting = false,
  error,
  copied = false,
  onDraft,
  onCopy,
  onEditDraft,
  labels,
  border = "bottom",
  ...props
}: CandidateOutreachComposerProps<TValue>) {
  const wording = { ...LABELS, ...labels };
  const channelLabel = channels.find((option) => option.value === channel)?.label ?? channel;

  return (
    <PanelSection data-slot="candidate-outreach-composer" border={border} {...props}>
      <SectionHeader
        label={wording.title}
        action={(
          <Stack direction="horizontal" gap="xs" align="center">
            {channels.map((option) => (
              <Button
                key={option.value}
                variant={channel === option.value ? "default" : "outline"}
                size="compact"
                onClick={() => onChannelChange(option.value)}
              >
                {option.label}
              </Button>
            ))}
          </Stack>
        )}
      />

      {guidance.editing ? (
        <Stack direction="vertical" gap="xs" marginBottom="md" radius="md" border="dashed" padding="sm">
          <Stack direction="horizontal" gap="none" align="center" justify="between">
            <Text variant="micro" as="span" weight="medium" tone="muted" transform="uppercase">
              {wording.guidanceHeading(channelLabel)}
            </Text>
            <Button type="button" variant="link-muted" size="bare" onClick={() => guidance.onReset()}>
              {wording.reset}
            </Button>
          </Stack>
          <Textarea
            value={guidance.value}
            onChange={(event) => guidance.onChange(event.target.value)}
            rows={2}
            textSize="xs"
            autoFocus
          />
          <Stack direction="horizontal" gap="xs" justify="end">
            <Button size="micro" variant="ghost" onClick={() => guidance.onCancel()}>{wording.cancel}</Button>
            <Button
              size="micro"
              onClick={() => guidance.onSave()}
              disabled={!!guidance.saving || guidance.canSave === false}
            >
              {guidance.saving ? <Icon icon={Loader2} size="xs" spin /> : wording.save}
            </Button>
          </Stack>
        </Stack>
      ) : (
        <Button type="button" variant="quiet" size="tone" onClick={() => guidance.onEdit()}>
          <Icon icon={Settings2} size="xs" tone="muted" />
          <Text variant="micro" as="span" tone="muted" truncate grow align="start">{guidance.text}</Text>
          {guidance.custom && <Badge as="span" variant="info" size="tiny" weight="normal" shrink>{wording.custom}</Badge>}
        </Button>
      )}

      {!draft ? (
        <Button variant="outline" size="sm" width="full" onClick={() => onDraft()} disabled={drafting}>
          <Icon icon={drafting ? Loader2 : MessageSquare} size="sm" spin={drafting} />
          {drafting ? wording.drafting : wording.draft(channelLabel)}
        </Button>
      ) : (
        <Stack direction="vertical" gap="sm">
          {draft.subject != null && draft.subject !== false && (
            <Text as="div" variant="inherit" size="xs">
              <Text variant="inherit" as="span" tone="muted">{wording.subject}</Text>
              <Text variant="inherit" as="span" weight="medium">{draft.subject}</Text>
            </Text>
          )}
          <Textarea value={draft.message} onChange={(event) => onEditDraft(event.target.value)} rows={6} textSize="xs" />
          <Stack direction="horizontal" gap="none" align="center" justify="between">
            <Text variant="micro" as="span" tone="muted">
              {present(draft.tone) ? <>{wording.tone}{draft.tone}</> : null}
            </Text>
            <Stack direction="horizontal" gap="xs">
              <Button variant="outline" size="compact" onClick={() => onDraft()} disabled={drafting}>
                <Icon icon={drafting ? Loader2 : RefreshCw} size="xs" spin={drafting} marginEnd="md" />
                {wording.redo}
              </Button>
              <Button variant="default" size="compact" onClick={() => onCopy()}>
                <Icon icon={copied ? Check : Copy} size="xs" marginEnd="md" />
                {copied ? wording.copied : wording.copy}
              </Button>
            </Stack>
          </Stack>
        </Stack>
      )}
      {present(error) && <Text size="xs" tone="destructive" marginTop="xs">{error}</Text>}
    </PanelSection>
  );
}

import { AgentComment } from "@epicbagel/saas-kit/primitives/agent-comment";
import { Callout } from "@epicbagel/saas-kit/primitives/callout";
