 * Trigger props such as `controlSize`, `width`, `textSize`, `grow`, `shrink`
 * and `title` pass straight to the kit's select trigger, which is marked
 * `data-slot="candidate-stage-select"`. The host owns the stages, their
 * wording and the move itself.
 */
export function CandidateStageSelect<TValue extends string = string>({
  value,
  options,
  onChange,
  itemSize,
  disabled,
  textSize,
  ...trigger
}: CandidateStageSelectProps<TValue>) {
  return (
    <Select value={value} onValueChange={(next) => onChange(next as TValue)} disabled={disabled}>
      <SelectTrigger textSize={textSize} {...trigger} data-slot="candidate-stage-select">
        <SelectValue />
